    schadensresistenzen: ["Blitz", "Feuer", "Gift", "Kälte", "Wucht-, Stich- und Hiebschaden durch nicht-magische Angriffe"], schadensimmunitaeten: [], verwundbarkeiten: [], zustandsimmunitaeten: [],
