    bewegung: { "Gehen": "9 m" },
    attribute: { STR: 25, DEX: 9, CON: 23, INT: 10, WIS: 14, CHA: 13 },
    rettungswuerfe: { GES: 3, KON: 10, CHA: 5 },
    fertigkeiten: { "Athletik": 11, "Wahrnehmung": 6 },
    schadensresistenzen: [],
    schadensimmunitaeten: ["Feuer"],
    verwundbarkeiten: [],
