    rk: 15, ruestungstyp: "Flickwerkrüstung",
    tp: 138, tp_wuerfel: "12W12+60",
    bewegung: { "Gehen": "12 m" },
    attribute: { STR: 23, DEX: 9, CON: 21, INT: 9, WIS: 10, CHA: 12 },
