    fertigkeiten: { "Arkane Kunde": 18, "Geschichte": 12, "Motiv erkennen": 9, "Wahrnehmung": 9 },
    schadensresistenzen: ["Blitz", "Kälte", "Nekrotisch"],
    schadensimmunitaeten: ["Gift", "Wucht-, Stich- und Hiebschaden durch nicht-magische Waffen"],
    verwundbarkeiten: [],
    zustandsimmunitaeten: ["Bezaubert", "Erschöpft", "Gelähmt", "Verängstigt", "Vergiftet"],
