    schadensresistenzen: ["Blitz", "Feuer", "Kälte", "Wucht-, Stich- und Hiebschaden durch nicht-magische Angriffe"],
    schadensimmunitaeten: ["Gift"],
    verwundbarkeiten: [],
    zustandsimmunitaeten: ["Vergiftet"],
    sinne: ["Dunkelsicht 36 m"], passiveWahrnehmung: 10,
