    attribute: { STR: 28, DEX: 10, CON: 20, INT: 3, WIS: 10, CHA: 9 },
    rettungswuerfe: { GES: 4, KON: 9, WEI: 4, CHA: 3 },
    fertigkeiten: { "Wahrnehmung": 4 },
    schadensresistenzen: [],
