    cr: 0.5, xp: 100,
    rk: 12, ruestungstyp: "natürliche Rüstung",
    tp: 22, tp_wuerfel: "4W8+4",
    bewegung: { "Gehen": "9 m", "Schwimmen": "12 m" },
    attribute: { STR: 13, DEX: 11, CON: 12, INT: 12, WIS: 13, CHA: 9 },
    rettungswuerfe: {},
