    schadensresistenzen: ["Blitz", "Feuer", "Kälte", "Säure", "Schall", "Wucht-, Stich- und Hiebschaden von nichtmagischen Angriffen"],
    schadensimmunitaeten: ["Gift", "Nekrotisch"],
    verwundbarkeiten: ["Gleißend"],
    zustandsimmunitaeten: ["Erschöpfung", "Festgesetzt", "Gelähmt", "Gepackt", "Liegend", "Verängstigt", "Vergiftet", "Versteinert"],
    sinne: ["Dunkelsicht 18 m"],
