    attribute: { STR: 18, DEX: 15, CON: 16, INT: 6, WIS: 12, CHA: 8 },
    rettungswuerfe: {},
    fertigkeiten: {},
    schadensresistenzen: [],
    schadensimmunitaeten: [],
