    schadensresistenzen: [], schadensimmunitaeten: ["Kälte"], verwundbarkeiten: [], zustandsimmunitaeten: [],
    sinne: ["Blindsicht 18 m", "Dunkelsicht 36 m"], passiveWahrnehmung: 23,
